parameters.jsCode:
const item = $input.first().json.body || $input.first().json;

// Mandatory field check
if (!item.email || !item.name) {
  throw new Error('Validation Failed: Missing required email or name');
}

// Clean and normalize email & domain
const email = item.email.trim().toLowerCase();
const domain = email.split('@')[1];

// Detect free/generic email domains
const genericDomains = ['gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com', 'icloud.com'];
const isCompanyDomain = !genericDomains.includes(domain);

return [{
  json: {
    raw_name: item.name.trim(),
    email: email,
    phone: item.phone ? item.phone.trim() : null,
    company: item.company ? item.company.trim() : (isCompanyDomain ? domain.split('.')[0].toUpperCase() : 'Unknown'),
    domain: isCompanyDomain ? domain : (item.website ? item.website.replace(/^https?:\/\//, '').replace(/\/.*$/, '') : null),
    notes: item.notes || item.message || '',
    submitted_at: new Date().toISOString(),
    is_b2b_domain: isCompanyDomain
  }
}];

